{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Rilzabrutinib, the closest retrieved analogue sharing the pyrazolo[3,4-d]pyrimidine core, phenoxyphenyl group, piperidine amide, and covalent acrylamide-type warhead, has an absolute oral bioavailability of only 4.7% in humans after a 400 mg tablet, far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Acalabrutinib, a related BTK inhibitor with a different imidazopyrazine core, has an absolute oral bioavailability of 25.3%, above the 20% threshold; however, its lower structural similarity to the query limits transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is ibrutinib, a pyrazolo[3,4-d]pyrimidine BTK inhibitor with an acrylamide warhead. The closest retrieved analogue rilzabrutinib shares the same core and phenoxyphenyl/piperidine-acrylamide architecture and has absolute oral bioavailability of only ~5% in humans, strongly supporting F <20%. The only above-threshold analogue in the same class, acalabrutinib, has a different heteroaromatic core and much lower similarity, so it does not outweigh the close-analogue evidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the query itself is included in the retrieved evidence set.",
    "The closest analogue rilzabrutinib differs by a cyanoacrylamide warhead and an additional bulky amine substituent; these differences could alter metabolic stability, but the direction is consistent with the query's known low-F class behavior.",
    "Acalabrutinib shows that related BTK inhibitors can exceed 20% F, but its lower similarity leaves some uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

